head.script:

scwin.onpageload = function() {
	scwin.btn_createWin_onclick();
	scwin.btn_createWin_onclick();
	scwin.btn_createWin_onclick();
	scwin.btn_createWin_onclick();
	scwin.btn_createWin_onclick();
	scwin.btn_createWin_onclick();
	scwin.btn_createWin_onclick();
};

scwin.onpageunload = function() {

};

scwin.windowIdx = 0;

scwin.btn_createWin_onclick = function(e) {
	var windowId = "window" + scwin.windowIdx++;
	var option = {
		title : windowId,
		src : "windowContainer_changeActiveWindow_WESE-200_(WSQ-5086)_sub.xml",
		windowTitle : windowId,
		windowId : windowId,
		openAction : "existWindow",
		frameMode : "wframe",
		fixed : false,
		defaultWidth :  "700px",
		defaultHeight : "700px",
		closeAction : function(title) {
			var closeFunc = windowContainer1.getWindow(windowContainer1.getSelectedWindowId()).scwin.onpageunload;
			if (typeof closeFunc === "function") {
				return closeFunc();
			};
		},
		dataObject : { 
			type : "json", 
			name : "paramData", 
			data : {}
		}
	};
	windowContainer1.createWindow(option);
};

scwin.checkVal = function() {
	return WebSquare.wUnit.getJq('#windowContainer1_nameLayer_'+$p.id+'windowContainer1_subWindow5').hasClass('w2windowContainer_selectedNameLayer');
}
scwin.unitTest = function() {
	//Unit
	WebSquare.wUnit.start();
	WebSquare.wUnit.addCommand("pause", "500");
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('#windowContainer1').width('700')");
	WebSquare.wUnit.addCommand("pause", "400");
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('windowContainer1_left').click()");
	WebSquare.wUnit.addCommand("pause", "400");
	WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
	WebSquare.wUnit.addCommand("pause", "500");
	//Run test and stop
	WebSquare.wUnit.run();
	WebSquare.wUnit.stop();
}	
scwin.unitTest()
